import{_ as a,o as e,c as n,a7 as i}from"./chunks/framework.BCbKzsgW.js";const u=JSON.parse('{"title":"幂等、重试与故障恢复","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"development/common/task-scheduling/execution/reliability.md","filePath":"development/common/task-scheduling/execution/reliability.md","lastUpdated":1793441194000}'),r={name:"development/common/task-scheduling/execution/reliability.md"};function d(s,t,o,l,h,p){return e(),n("div",null,[...t[0]||(t[0]=[i(`<h1 id="mi-dengchong-shi-yu-gu-zhang-hui-fu" tabindex="-1">幂等、重试与故障恢复 <a class="header-anchor" href="#mi-dengchong-shi-yu-gu-zhang-hui-fu" aria-label="Permalink to &quot;幂等、重试与故障恢复&quot;">​</a></h1><p>可靠执行需要分别处理任务没有送到、动作没有完成、动作已经完成但确认丢失。后两种情况对调度器可能表现为同一种超时，直接重试会产生重复副作用。</p><h2 id="chong-fu-lai-zi-na-li" tabindex="-1">重复来自哪里 <a class="header-anchor" href="#chong-fu-lai-zi-na-li" aria-label="Permalink to &quot;重复来自哪里&quot;">​</a></h2><table tabindex="0"><thead><tr><th>故障位置</th><th>恢复行为</th><th>业务风险</th></tr></thead><tbody><tr><td>发布成功后，未保存发布结果</td><td>投递器再次发布</td><td>同一事件重复到达</td></tr><tr><td>业务事务提交后，未确认消息</td><td>消息重新投递</td><td>同一业务动作重复处理</td></tr><tr><td>Worker 暂停超过租约</td><td>其他 Worker 重新领取</td><td>新旧尝试可能同时执行</td></tr><tr><td>外部接口已成功，响应丢失</td><td>调用方超时重试</td><td>重复发送、扣款或创建资源</td></tr></tbody></table><p>RabbitMQ 的<a href="https://www.rabbitmq.com/docs/confirms" target="_blank" rel="noreferrer">消费确认文档</a>说明了连接中断等情况下未确认消息的重新入队。可恢复的处理链路需要接受重复投递的可能，并在业务侧建立约束。</p><p>“至少一次”描述的是一定故障与存储保证下的投递或执行语义，不承诺业务动作最终必然成功。永久参数错误、耗尽重试、超出时效和不可用下游，都需要明确的终止与处置方式。</p><h2 id="tong-yi-shu-ju-ku-zhong-de-mi-deng" tabindex="-1">同一数据库中的幂等 <a class="header-anchor" href="#tong-yi-shu-ju-ku-zhong-de-mi-deng" aria-label="Permalink to &quot;同一数据库中的幂等&quot;">​</a></h2><p>以事件触发库存变更为例，去重记录与业务更新可以一起提交：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>BEGIN</span></span>
<span class="line"><span>  尝试插入 processed_events(event_id)，由唯一约束判重</span></span>
<span class="line"><span>  如果已经存在：结束本次重复处理</span></span>
<span class="line"><span>  执行业务状态更新</span></span>
<span class="line"><span>COMMIT</span></span>
<span class="line"><span>提交后再确认消息</span></span></code></pre></div><p>业务失败时去重记录也必须回滚。先单独提交“已经处理”，再执行业务，会让崩溃后的重试错误跳过尚未完成的动作。</p><p>事件 ID 只能去掉相同事件的重复。如果多个事件会要求同一动作，还需要业务键，例如 <code>order_id + notification_type + version</code>。键的保留期限要覆盖消息重放与历史修复窗口。</p><h2 id="wai-bu-fu-zuo-yong-de-bian-jie" tabindex="-1">外部副作用的边界 <a class="header-anchor" href="#wai-bu-fu-zuo-yong-de-bian-jie" aria-label="Permalink to &quot;外部副作用的边界&quot;">​</a></h2><p>本地插入唯一通知记录之后再调用供应商，仍有两个窗口：</p><table tabindex="0"><thead><tr><th>顺序</th><th>崩溃窗口</th><th>后果</th></tr></thead><tbody><tr><td>先记“已发送”，再发送</td><td>记完后尚未发送</td><td>可能漏发</td></tr><tr><td>先发送，再记“已发送”</td><td>已发送但尚未记录</td><td>重试可能重复发送</td></tr></tbody></table><p>因此，本地唯一约束只能约束本地记录，不能单独保证外部动作恰好发生一次。</p><p>如果下游支持幂等请求，每次尝试应携带相同的业务幂等键，并核对下游的作用范围、保存期限和参数一致性约束。<a href="https://docs.stripe.com/api/idempotent_requests" target="_blank" rel="noreferrer">Stripe 的幂等请求接口</a>是一个具体例子，其规则不代表所有供应商。</p><p>如果下游提供结果查询，超时后可以先查询原请求；查询也可能暂时不确定，需要继续核对。如果下游既不支持幂等也不能查询，就必须根据业务明确取舍重复与遗漏，或转人工处置，不能宣称端到端 Exactly-once。</p><h2 id="cuo-wu-fen-lei-yu-chong-shi-yu-suan" tabindex="-1">错误分类与重试预算 <a class="header-anchor" href="#cuo-wu-fen-lei-yu-chong-shi-yu-suan" aria-label="Permalink to &quot;错误分类与重试预算&quot;">​</a></h2><table tabindex="0"><thead><tr><th>错误</th><th>可以采取的处理</th><th>需要确认的条件</th></tr></thead><tbody><tr><td>网络中断、响应超时</td><td>查询结果或重试</td><td>动作是否可能已经提交</td></tr><tr><td>临时限流、服务过载</td><td>延迟重试、降低并发</td><td>下游恢复窗口和重试预算</td></tr><tr><td>参数、格式或版本错误</td><td>停止自动重试并诊断</td><td>数据或程序是否需要修复</td></tr><tr><td>凭据或权限错误</td><td>告警，按恢复流程处理</td><td>是否存在可恢复的凭据刷新</td></tr><tr><td>业务条件失效</td><td>记录 <code>skipped</code></td><td>不要计作基础设施失败</td></tr></tbody></table><p>指数退避可以用下面的示例表达。这里的第 1 次重试发生在首次失败之后，参数只是设计样例：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>base = 1 秒</span></span>
<span class="line"><span>cap = 5 分钟</span></span>
<span class="line"><span>第 k 次重试的等待时间 = random(0, min(cap, base × 2^(k - 1)))</span></span></code></pre></div><p>随机抖动把重试时间分散开；它不增加下游容量。AWS 的<a href="https://aws.amazon.com/builders-library/timeouts-retries-and-backoff-with-jitter/" target="_blank" rel="noreferrer">超时、重试与退避说明</a>分析了重试放大和同步重试的风险。</p><p>任务系统、HTTP 客户端和 SDK 都可能重试。配置时应计算总调用次数，并限制最大尝试次数、总处理时长和全局重试吞吐。可重新入队的任务，等待期间不必一直占用 Worker。</p><h2 id="san-lei-chao-shi" tabindex="-1">三类超时 <a class="header-anchor" href="#san-lei-chao-shi" aria-label="Permalink to &quot;三类超时&quot;">​</a></h2><ul><li>调用超时：本次等待外部接口多久，包括需要覆盖的连接与请求阶段。</li><li>执行租约：本次尝试多久不续租就允许回收。</li><li>业务截止时间：超过什么时间，继续执行已没有价值。</li></ul><p>三者需要协调。调用超时不意味着远端已经取消；租约过期不意味着旧 Worker 已停止；超过业务截止时间则应重新判断是否跳过，而非继续机械重试。</p><h2 id="gu-zhang-hui-fu-yu-ren-gong-chong-fang" tabindex="-1">故障恢复与人工重放 <a class="header-anchor" href="#gu-zhang-hui-fu-yu-ren-gong-chong-fang" aria-label="Permalink to &quot;故障恢复与人工重放&quot;">​</a></h2><p>租约回收只重新开放领取资格，仍要保留尝试上限。失去租约的 Worker 不应继续确认任务；涉及外部调用时，还需要下游幂等保护。</p><p>进入 <code>dead</code> 后，应保存错误类别、业务键、原始参数版本和尝试记录。人工重放前检查业务当前状态和已产生的副作用，修复根因后限速恢复。</p><p>同一业务动作重放时保留幂等键；如果确实需要发起新的业务动作，应建立新版本并记录原因。单纯更换随机 ID 绕过去重，会使修复过程难以审计。</p><h2 id="can-kao-zi-liao" tabindex="-1">参考资料 <a class="header-anchor" href="#can-kao-zi-liao" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><ul><li>RabbitMQ：<a href="https://www.rabbitmq.com/docs/confirms" target="_blank" rel="noreferrer">Consumer Acknowledgements and Publisher Confirms</a></li><li>Stripe：<a href="https://docs.stripe.com/api/idempotent_requests" target="_blank" rel="noreferrer">Idempotent requests</a></li><li>Amazon Builders&#39; Library：<a href="https://aws.amazon.com/builders-library/timeouts-retries-and-backoff-with-jitter/" target="_blank" rel="noreferrer">Timeouts, retries, and backoff with jitter</a></li></ul>`,32)])])}const b=a(r,[["render",d]]);export{u as __pageData,b as default};
